#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [suffix][middle][prefix]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n; placed++) {
        // Find where element (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) {
            if (p[i] == placed + 1) { pos = i; break; }
        }
        if (pos == placed) continue; // already in place

        // Step 1: Move element from pos to position (n-1) if it's not already there
        if (pos != n - 1) {
            // x = pos+1 (prefix includes 0..pos), y = n-1-pos (suffix is pos+1..n-1)
            // middle = elements between = none if pos+1 = n-1-pos... wait
            // We need x + y < n, x = pos+1, y = n-1-pos, x+y = n, not < n
            // So we need to leave at least 1 middle element
            // Use x = pos+1, y = n-1-pos-1 = n-pos-2 (leave one element in middle)
            // But y must be > 0, so n-pos-2 > 0 => pos < n-2
            if (pos < n - 2) {
                int x = pos + 1, y = n - pos - 2;
                // After: [suffix=p[n-y..n-1]][middle=p[x..n-y-1]][prefix=p[0..x-1]]
                // Element was at p[pos]=p[x-1], goes to end of new array (last of prefix block)
                // New position of element: y + (n-y-x) + pos = n - x + pos = n-1
                ops.push_back({x, y});
                apply(p, x, y);
            } else {
                // pos == n-2, element is at second-to-last position
                // Use x=1, y=1 to do a small rotation first if n>=3
                // Actually: x=pos, y=1 => prefix=p[0..pos-1], suffix=p[n-1], middle=p[pos..n-2]
                // After: [p[n-1]][p[pos]..p[n-2]][p[0]..p[pos-1]]
                // Element at pos goes to position 1. Then we handle it again.
                // Better: x=n-2, y=1 => moves last element to front, first n-2 to back
                // Element at n-2 ends up at position n-1 (last of prefix)
                int x = n - 2, y = 1;
                if (x > 0 && y > 0 && x + y < n) {
                    ops.push_back({x, y});
                    apply(p, x, y);
                }
            }
            // Re-find position
            pos = -1;
            for (int i = placed; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
            if (pos == placed) continue;
        }

        // Step 2: Element should be at position n-1 (or we try to place it)
        // Move from pos=n-1 to position=placed
        // x=placed, y=1 => but x must be >0, so placed>0 needed
        // After: [p[n-1]][p[placed]..p[n-2]][p[0]..p[placed-1]]
        if (placed > 0 && placed + 1 < n) {
            int x = placed, y = 1;
            ops.push_back({x, y});
            apply(p, x, y);
        } else if (placed == 0 && pos == n - 1) {
            // x=1, y= something to bring last to front
            int x = 1, y = n - 2;
            if (x > 0 && y > 0 && x + y < n) {
                ops.push_back({x, y});
                apply(p, x, y);
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
